// HasOrder applies the HasEdge predicate on the "order" edge.
func HasOrder() predicate.PaymentInvoiceRequest {
	return predicate.PaymentInvoiceRequest(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, true, OrderTable, OrderColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasOrderWith applies the HasEdge predicate on the "order" edge with a given conditions (other predicates).
func HasOrderWith(preds ...predicate.PaymentOrder) predicate.PaymentInvoiceRequest {
	return predicate.PaymentInvoiceRequest(func(s *sql.Selector) {
		step := newOrderStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasDocument applies the HasEdge predicate on the "document" edge.
func HasDocument() predicate.PaymentInvoiceRequest {
	return predicate.PaymentInvoiceRequest(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, false, DocumentTable, DocumentColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDocumentWith applies the HasEdge predicate on the "document" edge with a given conditions (other predicates).
func HasDocumentWith(preds ...predicate.PaymentInvoiceDocument) predicate.PaymentInvoiceRequest {
	return predicate.PaymentInvoiceRequest(func(s *sql.Selector) {
		step := newDocumentStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PaymentInvoiceRequest) predicate.PaymentInvoiceRequest {
	return predicate.PaymentInvoiceRequest(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PaymentInvoiceRequest) predicate.PaymentInvoiceRequest {
	return predicate.PaymentInvoiceRequest(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PaymentInvoiceRequest) predicate.PaymentInvoiceRequest {
	return predicate.PaymentInvoiceRequest(sql.NotPredicates(p))
}
